dashboard.definition:
{
 "title": "Wireless Client Details",
 "description": "One wireless client: name, IP, SSID, AP and radio, RSSI, SNR, speed, retry % and throughput over time, and the APs it was on.",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-4h@m,now"
   }
  },
  "input_site": {
   "type": "input.dropdown",
   "title": "Site",
   "dataSources": {
    "primary": "ds_sites"
   },
   "options": {
    "token": "site",
    "defaultValue": "ibk-lab",
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\")"
   }
  },
  "input_wlc": {
   "type": "input.dropdown",
   "title": "WLC",
   "dataSources": {
    "primary": "ds_wlc"
   },
   "options": {
    "token": "wlc",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"wlc\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"wlc\") | renameSeries(\"value\")"
   }
  },
  "input_client": {
   "type": "input.dropdown",
   "title": "Client",
   "dataSources": {
    "primary": "ds_clients"
   },
   "options": {
    "token": "tk_client",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"mac\") | renameSeries(\"value\")"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "90s",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_name": {
   "type": "splunk.singlevalue",
   "title": "Client name",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"device_hostname\")",
    "majorColor": "#708794"
   }
  },
  "viz_ip": {
   "type": "splunk.singlevalue",
   "title": "Client IP",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"ip_addr\")",
    "majorColor": "#708794"
   }
  },
  "viz_ssid": {
   "type": "splunk.singlevalue",
   "title": "SSID",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"vap_ssid\")",
    "majorColor": "#708794"
   }
  },
  "viz_ap": {
   "type": "splunk.singlevalue",
   "title": "AP",
   "dataSources": {
    "primary": "ds_ap_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"ap\")",
    "majorColor": "#708794"
   }
  },
  "viz_rssi_now": {
   "type": "splunk.singlevalue",
   "title": "RSSI",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"rssi\")",
    "majorColor": "#708794",
    "unit": "dBm",
    "unitPosition": "after"
   }
  },
  "viz_snr_now": {
   "type": "splunk.singlevalue",
   "title": "SNR",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"snr\")",
    "majorColor": "#708794",
    "unit": "dB",
    "unitPosition": "after"
   }
  },
  "viz_speed_now": {
   "type": "splunk.singlevalue",
   "title": "Speed",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"speed\")",
    "majorColor": "#708794",
    "unit": "Mb/s",
    "unitPosition": "after"
   }
  },
  "viz_radio": {
   "type": "splunk.singlevalue",
   "title": "Radio",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"radio\")",
    "majorColor": "#708794"
   }
  },
  "viz_rssi": {
   "type": "splunk.line",
   "title": "RSSI (dBm)",
   "dataSources": {
    "primary": "ds_rssi"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_snr": {
   "type": "splunk.line",
   "title": "SNR (dB)",
   "dataSources": {
    "primary": "ds_snr"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_speed": {
   "type": "splunk.line",
   "title": "Speed (Mb/s)",
   "dataSources": {
    "primary": "ds_speed"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_retries": {
   "type": "splunk.line",
   "title": "Retry %: retries as share of all transmissions (5 min)",
   "dataSources": {
    "primary": "ds_retries"
   },
   "options": {
    "legendDisplay": "bottom",
    "lineDashStylesByField": {
     "Problem above": "dash"
    },
    "seriesColorsByField": {
     "Retry %": "#1e93c6",
     "Problem above": "#dc4e41"
    }
   },
   "showProgressBar": true
  },
  "viz_throughput": {
   "type": "splunk.line",
   "title": "Throughput (kb/s)",
   "dataSources": {
    "primary": "ds_throughput"
   },
   "options": {
    "legendDisplay": "bottom"
   },
   "showProgressBar": true
  },
  "viz_roam_timeline": {
   "type": "splunk.timeline",
   "title": "Roaming timeline: one lane per AP; bars = time on the AP, dots = associations coloured by roam time (green < 100 ms, yellow 100-500 ms, red > 500 ms, grey first join)",
   "dataSources": {
    "primary": "ds_roam_timeline"
   },
   "options": {
    "x": "> primary | seriesByName(\"_time\")",
    "y": "> primary | seriesByName(\"ap\")",
    "duration": "> primary | seriesByName(\"duration\")",
    "durationUnit": "seconds",
    "category": "> primary | seriesByName(\"category\")",
    "dataColors": "> primary | seriesByName(\"category\") | matchValue(categoryColors)",
    "additionalTooltipFields": [
     "Roam type",
     "Band",
     "BSSID",
     "Roam time (ms)"
    ],
    "legendDisplay": "bottom"
   },
   "showProgressBar": true,
   "context": {
    "categoryColors": [
     {
      "match": "Connected",
      "value": "#5C6773"
     },
     {
      "match": "Join",
      "value": "#C9D1D9"
     },
     {
      "match": "Good",
      "value": "#118832"
     },
     {
      "match": "Slow",
      "value": "#CBA700"
     },
     {
      "match": "Bad",
      "value": "#D41F1F"
     }
    ]
   }
  },
  "viz_roam": {
   "type": "splunk.table",
   "title": "APs the client was on (a gap over 5 minutes starts a new row)",
   "dataSources": {
    "primary": "ds_roam_table"
   },
   "options": {
    "count": 20
   },
   "showProgressBar": true
  }
 },
 "dataSources": {
  "ds_sites": {
   "type": "ds.search",
   "name": "sites",
   "options": {
    "query": "| mcatalog values(site) as site WHERE `mdt_metrics_index` | mvexpand site | rename site as label | eval value=label"
   }
  },
  "ds_wlc": {
   "type": "ds.search",
   "name": "wlc",
   "options": {
    "query": "| mcatalog values(extracted_source) as wlc WHERE `mdt_metrics_index` site=\"$site$\" metric_name=mdt_wl_info_ap_ip_addr | mvexpand wlc"
   }
  },
  "ds_clients": {
   "type": "ds.search",
   "name": "clients",
   "options": {
    "query": "| mstats latest(_value) WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_client_stats_most_recent_rssi BY traffic_stats_ms_mac_address | rename traffic_stats_ms_mac_address as mac | join type=left mac [| mstats latest_time(_value) as t WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_device_hostname BY client_wsa_info_client_mac device_hostname | sort 0 - t | dedup client_wsa_info_client_mac | rename client_wsa_info_client_mac as mac | fields mac device_hostname] | eval label=if(isnotnull(device_hostname), device_hostname.\" (\".mac.\")\", mac) | sort label | table label mac"
   }
  },
  "ds_now": {
   "type": "ds.search",
   "name": "now",
   "options": {
    "query": "| mstats latest(mdt_wl_client_stats_most_recent_rssi) as rssi latest(mdt_wl_client_stats_most_recent_snr) as snr latest(mdt_wl_client_stats_speed) as speed WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" traffic_stats_ms_mac_address=\"$tk_client$\" | appendcols [| mstats latest_time(_value) as t WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_device_hostname BY client_wsa_info_client_mac device_hostname | sort 0 - t | dedup client_wsa_info_client_mac | rename client_wsa_info_client_mac as mac | fields mac device_hostname | where mac=\"$tk_client$\" | fields device_hostname] | appendcols [| mstats latest_time(_value) as t WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ip_addr sisf_db_mac_mac_addr=\"$tk_client$\" BY ip_addr | sort - t | head 1 | fields ip_addr] | appendcols [| mstats latest_time(_value) as t WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_vap_ssid dot11_oper_data_ms_mac_address=\"$tk_client$\" BY vap_ssid | sort - t | head 1 | fields vap_ssid] | appendcols [| mstats latest(mdt_wl_info_current_channel) as ch latest(mdt_wl_info_ms_ap_slot_id) as slot WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" dot11_oper_data_ms_mac_address=\"$tk_client$\"] | appendcols [| mstats latest_time(_value) as t WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ewlc_ms_phy_type dot11_oper_data_ms_mac_address=\"$tk_client$\" BY ewlc_ms_phy_type | sort - t | head 1 | eval phy=replace(ewlc_ms_phy_type, \"^client-dot11([a-z]+).*\", \"802.11\\\\1\") | fields phy] | eval device_hostname=coalesce(device_hostname, \"(none)\"), band=case(slot==2, \"6 GHz\", ch <= 14, \"2.4 GHz\", ch > 14, \"5 GHz\"), radio=if(isnotnull(ch), band.\" ch \".ch.if(isnotnull(phy), \", \".phy, \"\"), null())",
    "queryParameters": {
     "earliest": "-15m",
     "latest": "now"
    }
   }
  },
  "ds_metrics": {
   "type": "ds.search",
   "name": "metrics",
   "options": {
    "query": "| mstats latest(mdt_wl_client_stats_most_recent_rssi) as rssi latest(mdt_wl_client_stats_most_recent_snr) as snr latest(mdt_wl_client_stats_speed) as speed max(mdt_wl_client_stats_data_retries) as retries max(mdt_wl_client_stats_pkts_tx) as ptx max(mdt_wl_client_stats_bytes_tx) as btx max(mdt_wl_client_stats_bytes_rx) as brx WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" traffic_stats_ms_mac_address=\"$tk_client$\" span=1m | sort 0 _time | streamstats current=f last(retries) as pr last(ptx) as pp last(btx) as pbt last(brx) as pbr last(_time) as pt | eval dr=if(retries >= pr, retries - pr, null()), dp=if(ptx >= pp, ptx - pp, null()), dt=_time - pt | eval tx_kbps=if(btx >= pbt, round((btx - pbt) * 8 / dt / 1000, 1), null()), rx_kbps=if(brx >= pbr, round((brx - pbr) * 8 / dt / 1000, 1), null())"
   }
  },
  "ds_roam": {
   "type": "ds.search",
   "name": "roam",
   "options": {
    "query": "| mstats latest(_value) WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_client_stats_ap_mac_address dot11_oper_data_ms_mac_address=\"$tk_client$\" span=1m BY ap_mac_address | rename ap_mac_address as eth_mac | sort 0 _time | streamstats current=f last(eth_mac) as prev last(_time) as pt | eval new=if(isnull(prev) OR prev!=eth_mac OR _time - pt > 300, 1, 0) | streamstats sum(new) as stay | stats min(_time) as first max(_time) as last first(eth_mac) as eth_mac by stay | join type=left eth_mac [| mstats latest(_value) WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_eth_mac BY eth_mac ap_name_mac_map_wtp_name | join type=left eth_mac [| mstats latest(_value) WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_wtp_mac BY ethernet_mac_wtp_mac_map_ethernet_mac wtp_mac | rename ethernet_mac_wtp_mac_map_ethernet_mac as eth_mac] | join type=left wtp_mac [| mstats latest(_value) WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ap_ip_addr BY oper_data_wtp_mac ap_ip_addr | where ap_ip_addr!=\"0.0.0.0\" | rename oper_data_wtp_mac as wtp_mac] | join type=left wtp_mac [| mstats latest(_value) WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_info_location BY capwap_data_wtp_mac location | where location!=\"default location\" | rename capwap_data_wtp_mac as wtp_mac | fields wtp_mac location] | rename ap_name_mac_map_wtp_name as ap_name | fields eth_mac ap_name ap_ip_addr location] | sort - last"
   }
  },
  "ds_roam_timeline": {
   "type": "ds.search",
   "name": "roam_timeline",
   "options": {
    "query": "| mstats latest(_value) as run_latency WHERE `mdt_metrics_index` site=\"$site$\" extracted_source=\"$wlc$\" metric_name=mdt_wl_client_roam_run_latency client_mac=\"$tk_client$\" BY ap_name bssid roam_type slot assoc_time | dedup assoc_time | addinfo | eval start=strptime(substr(assoc_time, 1, 19).\" +0000\", \"%Y-%m-%dT%H:%M:%S %z\") | sort 0 - start | streamstats current=f last(start) as next_start | eval stop=coalesce(next_start, min(now(), info_max_time)), bar_start=max(start, info_min_time), ap=coalesce(ap_name, bssid), slot_n=tonumber(slot) | eval band=case(slot_n==0, \"2.4 GHz\", slot_n==1, \"5 GHz\", slot_n==2, \"6 GHz\", true(), \"slot \".slot) | eval roam=case(match(roam_type, \"11r\"), \"802.11r\", match(roam_type, \"okc\"), \"OKC\", match(roam_type, \"none\"), \"none\", true(), replace(roam_type, \"^dot11-roam-type-\", \"\")) | eval category_dot=case(match(roam_type, \"none\"), \"Join\", run_latency < 100, \"Good\", run_latency <= 500, \"Slow\", true(), \"Bad\") | eval kind=if(start >= info_min_time, mvappend(\"bar\", \"dot\"), \"bar\") | mvexpand kind | eval _time=if(kind==\"bar\", bar_start, start), duration=if(kind==\"bar\", stop - bar_start, null()), category=if(kind==\"bar\", \"Connected\", category_dot) | where kind==\"dot\" OR duration > 0 | rename roam as \"Roam type\", band as Band, bssid as BSSID, run_latency as \"Roam time (ms)\" | fields _time ap duration category \"Roam type\" Band BSSID \"Roam time (ms)\" | sort 0 _time"
   }
  },
  "ds_rssi": {
   "type": "ds.chain",
   "name": "rssi",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename rssi as \"RSSI (dBm)\" | fields _time \"RSSI (dBm)\""
   }
  },
  "ds_snr": {
   "type": "ds.chain",
   "name": "snr",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename snr as \"SNR (dB)\" | fields _time \"SNR (dB)\""
   }
  },
  "ds_speed": {
   "type": "ds.chain",
   "name": "speed",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename speed as \"Speed (Mb/s)\" | fields _time \"Speed (Mb/s)\""
   }
  },
  "ds_retries": {
   "type": "ds.chain",
   "name": "retries",
   "options": {
    "extend": "ds_metrics",
    "query": "| bin _time span=5m | stats sum(dr) as dr sum(dp) as dp by _time | where _time + 300 <= now() | eval \"Retry %\"=if(dp + dr > 0, round(dr / (dp + dr) * 100, 1), null()), \"Problem above\"=10 | fields _time \"Retry %\" \"Problem above\""
   }
  },
  "ds_throughput": {
   "type": "ds.chain",
   "name": "throughput",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename tx_kbps as \"TX (kb/s)\", rx_kbps as \"RX (kb/s)\" | fields _time \"TX (kb/s)\" \"RX (kb/s)\""
   }
  },
  "ds_ap_now": {
   "type": "ds.chain",
   "name": "ap_now",
   "options": {
    "extend": "ds_roam",
    "query": "| where last >= relative_time(now(), \"-15m\") | head 1 | eval ap=coalesce(ap_name, eth_mac) | fields ap"
   }
  },
  "ds_roam_table": {
   "type": "ds.chain",
   "name": "roam_table",
   "options": {
    "extend": "ds_roam",
    "query": "| eval AP=coalesce(ap_name, eth_mac), \"AP IP\"=ap_ip_addr, Location=location, \"First seen\"=strftime(first, \"%Y-%m-%d %H:%M\"), \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\") | table AP \"AP IP\" Location \"First seen\" \"Last seen\""
   }
  }
 },
 "layout": {
  "type": "grid",
  "globalInputs": [
   "input_time",
   "input_site",
   "input_wlc",
   "input_client"
  ],
  "layoutDefinitions": {
   "layout_1": {
    "type": "grid",
    "options": {
     "width": 1440,
     "height": 1570
    },
    "structure": [
     {
      "item": "viz_name",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 220,
       "h": 110
      }
     },
     {
      "item": "viz_ip",
      "type": "block",
      "position": {
       "x": 220,
       "y": 0,
       "w": 160,
       "h": 110
      }
     },
     {
      "item": "viz_ssid",
      "type": "block",
      "position": {
       "x": 380,
       "y": 0,
       "w": 160,
       "h": 110
      }
     },
     {
      "item": "viz_ap",
      "type": "block",
      "position": {
       "x": 540,
       "y": 0,
       "w": 180,
       "h": 110
      }
     },
     {
      "item": "viz_radio",
      "type": "block",
      "position": {
       "x": 720,
       "y": 0,
       "w": 260,
       "h": 110
      }
     },
     {
      "item": "viz_rssi_now",
      "type": "block",
      "position": {
       "x": 980,
       "y": 0,
       "w": 150,
       "h": 110
      }
     },
     {
      "item": "viz_snr_now",
      "type": "block",
      "position": {
       "x": 1130,
       "y": 0,
       "w": 150,
       "h": 110
      }
     },
     {
      "item": "viz_speed_now",
      "type": "block",
      "position": {
       "x": 1280,
       "y": 0,
       "w": 160,
       "h": 110
      }
     },
     {
      "item": "viz_rssi",
      "type": "block",
      "position": {
       "x": 0,
       "y": 110,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_snr",
      "type": "block",
      "position": {
       "x": 720,
       "y": 110,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_speed",
      "type": "block",
      "position": {
       "x": 0,
       "y": 390,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_retries",
      "type": "block",
      "position": {
       "x": 720,
       "y": 390,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_throughput",
      "type": "block",
      "position": {
       "x": 0,
       "y": 670,
       "w": 1440,
       "h": 280
      }
     },
     {
      "item": "viz_roam_timeline",
      "type": "block",
      "position": {
       "x": 0,
       "y": 950,
       "w": 1440,
       "h": 320
      }
     },
     {
      "item": "viz_roam",
      "type": "block",
      "position": {
       "x": 0,
       "y": 1270,
       "w": 1440,
       "h": 300
      }
     }
    ]
   }
  },
  "tabs": {
   "items": [
    {
     "label": "Client",
     "layoutId": "layout_1"
    }
   ]
  }
 },
 "applicationProperties": {}
}
